/**
 * The random Pokémon generator's rules (pure, client-safe): who's in the pool
 * for the options picked, a roll of 1 to 6 different Pokémon, a re-roll of one
 * slot that keeps the others, and the share link that rebuilds a roll exactly.
 * Data: the Daily Dex facts for all 1,025 Pokémon (PokéAPI, generated by
 * scripts/build-daily-dex.ts). Names, numbers and types only, never art
 * (the Pokémon imagery rule).
 */

import { DEX_ROWS, type DexRow } from "@/data/originals/daily-dex-facts";

export interface GenPokemon { dex: number; name: string; gen: number; types: string[]; stage: DexRow[4]; legendary: boolean; category: string; height: number; weight: number }

export const ALL_POKEMON: GenPokemon[] = DEX_ROWS.map((r) => ({
  dex: r[0], name: r[1], gen: r[2], types: r[3], stage: r[4], category: r[8], height: r[6], weight: r[7], legendary: r[9] === 1,
}));
const BY_DEX = new Map(ALL_POKEMON.map((p) => [p.dex, p]));
export const pokemonByDex = (dex: number) => BY_DEX.get(dex) ?? null;

export const GENERATIONS = [...new Set(ALL_POKEMON.map((p) => p.gen))].sort((a, b) => a - b);
export const GEN_REGIONS: Record<number, string> = { 1: "Kanto", 2: "Johto", 3: "Hoenn", 4: "Sinnoh", 5: "Unova", 6: "Kalos", 7: "Alola", 8: "Galar", 9: "Paldea" };
export const TYPES = ["Normal", "Fire", "Water", "Grass", "Electric", "Ice", "Fighting", "Poison", "Ground", "Flying", "Psychic", "Bug", "Rock", "Ghost", "Dragon", "Dark", "Steel", "Fairy"];
export const COUNTS = [6, 3, 1] as const;
export type GenCount = (typeof COUNTS)[number];

export interface GenOptions {
  /** One generation (1 to 9), or null for all. */
  gen: number | null;
  /** One type (either slot), or null for any. */
  type: string | null;
  /** Only Pokémon that don't evolve further (final stages and ones that never evolve). */
  fullyEvolved: boolean;
  /** Leave out Legendary and Mythical Pokémon. */
  noLegendary: boolean;
  /** No two rolled Pokémon share a type. */
  noRepeatTypes: boolean;
}

export const DEFAULT_OPTIONS: GenOptions = { gen: null, type: null, fullyEvolved: false, noLegendary: false, noRepeatTypes: false };

/** Everyone the options allow. */
export function genPool(o: GenOptions): GenPokemon[] {
  return ALL_POKEMON.filter((p) =>
    (o.gen == null || p.gen === o.gen)
    && (o.type == null || p.types.includes(o.type))
    && (!o.fullyEvolved || p.stage === "Final" || p.stage === "Single")
    && (!o.noLegendary || !p.legendary));
}

type Rng = () => number;

/** Could this Pokémon join these others? (different, and no shared type when asked) */
function fits(p: GenPokemon, others: GenPokemon[], o: GenOptions): boolean {
  if (others.some((x) => x.dex === p.dex)) return false;
  if (o.noRepeatTypes && others.some((x) => x.types.some((t) => p.types.includes(t)))) return false;
  return true;
}

function pick<T>(xs: T[], rng: Rng): T | null {
  return xs.length ? xs[Math.floor(rng() * xs.length)] : null;
}

/**
 * Up to `count` different Pokémon from the pool. With no repeated types the
 * roll can come up short when the pool runs out of new types (a type filter
 * makes every Pokémon share it); it returns as many as fit.
 */
export function rollPokemon(count: number, o: GenOptions, rng: Rng = Math.random): GenPokemon[] {
  const pool = genPool(o);
  // A type filter plus no repeated types can only ever give one: the filtered type is shared by all.
  const out: GenPokemon[] = [];
  for (let i = 0; i < count; i++) {
    const next = pick(pool.filter((p) => fits(p, out, o)), rng);
    if (!next) break;
    out.push(next);
  }
  return out;
}

/** A new Pokémon for one slot, keeping the others (and staying different from them). */
export function rerollSlot(current: (GenPokemon | null)[], index: number, o: GenOptions, rng: Rng = Math.random): GenPokemon | null {
  const others = current.filter((p, i): p is GenPokemon => i !== index && !!p);
  const pool = genPool(o).filter((p) => fits(p, others, o) && p.dex !== current[index]?.dex);
  return pick(pool, rng) ?? current[index] ?? null;
}

/** Why a roll can't fill every slot, or null. */
export function shortfall(count: number, got: number, o: GenOptions): string | null {
  if (got >= count) return null;
  if (!got) return "No Pokémon match these options. Try fewer filters.";
  if (o.noRepeatTypes && o.type) return `Every Pokémon here is ${o.type} type, so with no repeated types only one fits.`;
  if (o.noRepeatTypes) return `Only ${got} can roll without sharing a type. Switch off no repeated types for more.`;
  return `Only ${got} Pokémon match these options.`;
}

// ── Share links ─────────────────────────────────────────────────────────────
// ?p=6-134-254&gen=1&type=Fire&fe=1&nl=1&nr=1&n=6 rebuilds the roll and the options.

export function linkParams(rolled: (GenPokemon | null)[], count: number, o: GenOptions): URLSearchParams {
  const q = new URLSearchParams();
  const dexes = rolled.filter((p): p is GenPokemon => !!p).map((p) => p.dex);
  if (dexes.length) q.set("p", dexes.join("-"));
  if (count !== 6) q.set("n", String(count));
  if (o.gen != null) q.set("gen", String(o.gen));
  if (o.type) q.set("type", o.type);
  if (o.fullyEvolved) q.set("fe", "1");
  if (o.noLegendary) q.set("nl", "1");
  if (o.noRepeatTypes) q.set("nr", "1");
  return q;
}

export function readLink(q: URLSearchParams): { rolled: GenPokemon[]; count: GenCount; options: GenOptions } | null {
  const n = Number(q.get("n") ?? 6);
  const count = (COUNTS as readonly number[]).includes(n) ? (n as GenCount) : 6;
  const gen = Number(q.get("gen"));
  const type = q.get("type");
  const options: GenOptions = {
    gen: GENERATIONS.includes(gen) ? gen : null,
    type: type && TYPES.includes(type) ? type : null,
    fullyEvolved: q.get("fe") === "1",
    noLegendary: q.get("nl") === "1",
    noRepeatTypes: q.get("nr") === "1",
  };
  const rolled = (q.get("p") ?? "").split("-").map(Number).map(pokemonByDex).filter((p): p is GenPokemon => !!p).slice(0, count);
  if (!rolled.length && !q.has("gen") && !q.has("type") && !q.has("n")) return null;
  return { rolled, count, options };
}
